package main

import (
	"bufio"
	"bytes"
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"regexp"
	"runtime"
	"strings"
	"sync"
)

// THE GAUNTLET'S GENERATED FILES ARE A FUNCTION OF THEIR SOURCES.
//
// The harnesses in gauntlet/go, gauntlet/js and gauntlet/java call committed
// copies of generated code, and a benchmark measures whatever copy is there. Let
// G(e) be the file the compiler at HEAD writes for an entry e of
// gauntlet/regen.txt. The claim every benchmark rests on is committed(e) = G(e)
// for each e, and this step decides it, byte for byte.
//
// Until gauntlet-2026-09-29 the copies were regenerated by hand, if at all, and
// all 26 were the term backends' output of August; then regen.sh was the one
// list, run by hand, and it failed silently from the J switch to work-2026-10-22,
// so gen_report_native.go was a week stale. A list nothing runs is a list nothing
// checks: now every check runs it.

// regenEntry is one line of gauntlet/regen.txt.
type regenEntry struct {
	target, source, name, out string
	host                      string // "js" or "java" for a ported source, else ""
	line                      int
}

func readRegenList(root string) ([]regenEntry, error) {
	f, err := os.Open(filepath.Join(root, "gauntlet", "regen.txt"))
	if err != nil {
		return nil, err
	}
	defer f.Close()
	var out []regenEntry
	sc := bufio.NewScanner(f)
	for n := 1; sc.Scan(); n++ {
		line := strings.TrimSpace(sc.Text())
		if line == "" || strings.HasPrefix(line, "#") {
			continue
		}
		fs := strings.Fields(line)
		if len(fs) != 4 {
			return nil, fmt.Errorf("gauntlet/regen.txt:%d: want target, source, name and output, got %q", n, line)
		}
		e := regenEntry{target: fs[0], source: fs[1], name: fs[2], out: fs[3], line: n}
		for _, h := range []string{"js", "java"} {
			if p, ok := strings.CutPrefix(e.source, h+":"); ok {
				e.host, e.source = h, p
			}
		}
		out = append(out, e)
	}
	return out, sc.Err()
}

// useGo is a line importing Go's root module.
var useGo = regexp.MustCompile(`(?m)^use go$`)

// port is a program written against Go's names, read with host's: the import of
// Go's root module becomes host's, and every `go.` prefix host's (jsontok-2026-08-26
// §6). It is regen.sh's former `sed -e 's/^use go$/use H/' -e 's/go[.]/H./g'`.
func port(src, host string) string {
	return strings.ReplaceAll(useGo.ReplaceAllString(src, "use "+host), "go.", host+".")
}

// buildGen builds cmd/gen into the work directory.
func (c *checker) buildGen() (string, error) {
	gen := filepath.Join(c.work, "bin", "gen-gauntlet")
	if runtime.GOOS == "windows" {
		gen += ".exe"
	}
	build := exec.Command("go", "build", "-o", gen, "./cmd/gen")
	build.Dir = c.root
	if out, err := build.CombinedOutput(); err != nil {
		return "", fmt.Errorf("building cmd/gen: %v\n%s", err, out)
	}
	return gen, nil
}

// regenerate writes G(e) under dir for every entry, in parallel, and returns the
// first failure of each entry that failed.
func (c *checker) regenerate(gen, dir string, entries []regenEntry) []error {
	scratch := filepath.Join(c.work, "gauntlet-ported")
	if err := os.RemoveAll(scratch); err != nil {
		return []error{err}
	}
	if err := os.MkdirAll(scratch, 0o755); err != nil {
		return []error{err}
	}
	errs := make([]error, len(entries))
	var wg sync.WaitGroup
	sem := make(chan struct{}, max(c.jobs, 1))
	for i, e := range entries {
		wg.Add(1)
		go func() {
			defer wg.Done()
			sem <- struct{}{}
			defer func() { <-sem }()
			errs[i] = c.regenerateOne(gen, dir, scratch, e)
		}()
	}
	wg.Wait()
	var out []error
	for _, err := range errs {
		if err != nil {
			out = append(out, err)
		}
	}
	return out
}

func (c *checker) regenerateOne(gen, dir, scratch string, e regenEntry) error {
	src, err := os.ReadFile(filepath.Join(c.root, e.source))
	if err != nil {
		return fmt.Errorf("gauntlet/regen.txt:%d: %v", e.line, err)
	}
	path := e.source
	if e.host != "" {
		base := strings.TrimSuffix(filepath.Base(e.source), ".oro")
		path = filepath.Join(scratch, base+"-"+e.host+".oro")
		if err := os.WriteFile(path, []byte(port(string(src), e.host)), 0o644); err != nil {
			return err
		}
	}
	first, _, _ := strings.Cut(string(src), "\n")
	var args []string
	if needsChecked(e.source, first) {
		args = append(args, "-checked")
	}
	dst := filepath.Join(dir, filepath.FromSlash(e.out))
	if err := os.MkdirAll(filepath.Dir(dst), 0o755); err != nil {
		return err
	}
	args = append(args, "-name", e.name, path, e.target, dst)
	cmd := exec.Command(gen, args...)
	cmd.Dir = c.root
	var stderr bytes.Buffer
	cmd.Stderr = &stderr
	if err := cmd.Run(); err != nil {
		return fmt.Errorf("%s (gauntlet/regen.txt:%d): %v\n%s", e.out, e.line, err, tail(stderr.String(), 10))
	}
	return nil
}

// gauntlet is the step: regenerate every file into the work directory and
// compare each with the committed copy.
func (c *checker) gauntlet() result {
	entries, err := readRegenList(c.root)
	if err != nil {
		return result{status: fail, detail: err.Error()}
	}
	gen, err := c.buildGen()
	if err != nil {
		return result{status: fail, detail: err.Error()}
	}
	dir := filepath.Join(c.work, "gauntlet")
	if err := os.RemoveAll(dir); err != nil {
		return result{status: fail, detail: err.Error()}
	}
	if errs := c.regenerate(gen, dir, entries); len(errs) > 0 {
		for _, e := range errs {
			fmt.Println("   │ " + strings.ReplaceAll(e.Error(), "\n", "\n   │ "))
		}
		return result{status: fail, detail: fmt.Sprintf("%d of %d gauntlet files failed to generate", len(errs), len(entries))}
	}
	stale := staleFiles(c.root, dir, entries)
	if len(stale) > 0 {
		for _, s := range stale {
			fmt.Println("   │ " + s)
		}
		return result{status: fail, detail: fmt.Sprintf("%d of %d gauntlet files are not what the compiler writes: "+
			"run `bash gauntlet/regen.sh`, and time the harnesses that call them (the rule for emission)", len(stale), len(entries))}
	}
	return result{status: pass, detail: fmt.Sprintf("%d gauntlet files, each byte-identical to its regeneration", len(entries))}
}

// staleFiles names each entry whose committed copy differs from its regeneration
// under dir, or is missing.
func staleFiles(root, dir string, entries []regenEntry) []string {
	var out []string
	for _, e := range entries {
		want, err := os.ReadFile(filepath.Join(dir, filepath.FromSlash(e.out)))
		if err != nil {
			out = append(out, e.out+": not regenerated: "+err.Error())
			continue
		}
		have, err := os.ReadFile(filepath.Join(root, filepath.FromSlash(e.out)))
		switch {
		case err != nil:
			out = append(out, e.out+": not committed")
		case !bytes.Equal(have, want):
			out = append(out, e.out+": differs from what "+e.source+" generates")
		}
	}
	return out
}

// regenInto is `check -regen DIR`, which regen.sh runs: write every gauntlet file
// under DIR, `.` being the gauntlet itself.
func (c *checker) regenInto(dir string) error {
	entries, err := readRegenList(c.root)
	if err != nil {
		return err
	}
	gen, err := c.buildGen()
	if err != nil {
		return err
	}
	if !filepath.IsAbs(dir) {
		wd, err := os.Getwd()
		if err != nil {
			return err
		}
		dir = filepath.Join(wd, dir)
	}
	if errs := c.regenerate(gen, dir, entries); len(errs) > 0 {
		return errs[0]
	}
	for _, e := range entries {
		fmt.Println(e.out)
	}
	return nil
}
